-- Local lifecycle changes permanently retire the old background authority,
-- even when a user, identity or personal membership is subsequently restored.
-- Keep encrypted credentials for the existing durable remote revocation outbox.
-- Invalidate in-flight issuance too, so a late remote response cannot publish.
-- Single-line triggers are required by the remote D1 migration runner.
CREATE TRIGGER hybrag_lifecycle_user_disabled AFTER UPDATE OF is_disabled ON users WHEN NEW.is_disabled=1 AND OLD.is_disabled=0 BEGIN DELETE FROM hybrag_delegation_issuance WHERE user_id=OLD.id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND user_id=OLD.id; END;
CREATE TRIGGER hybrag_lifecycle_user_deleted BEFORE DELETE ON users  BEGIN DELETE FROM hybrag_delegation_issuance WHERE user_id=OLD.id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND user_id=OLD.id; END;
CREATE TRIGGER hybrag_lifecycle_identity_deleted BEFORE DELETE ON user_identities WHEN OLD.provider='vos' BEGIN DELETE FROM hybrag_delegation_issuance WHERE user_id=OLD.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND user_id=OLD.user_id; END;
CREATE TRIGGER hybrag_lifecycle_identity_changed AFTER UPDATE OF provider,subject,user_id ON user_identities WHEN OLD.provider='vos' AND (NEW.provider IS NOT OLD.provider OR NEW.subject IS NOT OLD.subject OR NEW.user_id IS NOT OLD.user_id) BEGIN DELETE FROM hybrag_delegation_issuance WHERE user_id=OLD.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND user_id=OLD.user_id; END;
CREATE TRIGGER hybrag_lifecycle_workspace_deleted BEFORE DELETE ON workspaces  BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=OLD.id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=OLD.id; END;
CREATE TRIGGER hybrag_lifecycle_workspace_shared AFTER UPDATE OF is_personal ON workspaces WHEN OLD.is_personal=1 AND NEW.is_personal=0 BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=OLD.id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=OLD.id; END;
CREATE TRIGGER hybrag_lifecycle_owner_deleted BEFORE DELETE ON workspace_members WHEN OLD.role='owner' BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=OLD.workspace_id AND user_id=OLD.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=OLD.workspace_id AND user_id=OLD.user_id; END;
CREATE TRIGGER hybrag_lifecycle_owner_changed AFTER UPDATE OF role,user_id,workspace_id ON workspace_members WHEN OLD.role='owner' AND (NEW.role IS NOT OLD.role OR NEW.user_id IS NOT OLD.user_id OR NEW.workspace_id IS NOT OLD.workspace_id) BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=OLD.workspace_id AND user_id=OLD.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=OLD.workspace_id AND user_id=OLD.user_id; END;
CREATE TRIGGER hybrag_lifecycle_peer_added AFTER INSERT ON workspace_members  BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=NEW.workspace_id AND user_id<>NEW.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=NEW.workspace_id AND user_id<>NEW.user_id; END;
CREATE TRIGGER hybrag_lifecycle_peer_moved AFTER UPDATE OF workspace_id,user_id ON workspace_members WHEN NEW.workspace_id IS NOT OLD.workspace_id OR NEW.user_id IS NOT OLD.user_id BEGIN DELETE FROM hybrag_delegation_issuance WHERE workspace_id=NEW.workspace_id AND user_id<>NEW.user_id; UPDATE hybrag_delegations SET state='revoking',version=version+1,next_attempt_at='',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='active' AND workspace_id=NEW.workspace_id AND user_id<>NEW.user_id; END;

